export type User = { id: string; role: "user" | "admin" };
export type Invoice = { ownerId: string };
// Policy: only the owner or an admin may read an invoice.
export function canReadInvoice(user: User | undefined, invoice: Invoice): boolean {
  return user !== undefined;
}
